mapper.select:
SELECT a.*, b.MAX_PREIOD_CODE, c.TEMP_TYPE_NAME AS TYPE_DSCR FROM `inspection`.`inspection_routine_period` a LEFT JOIN (SELECT a.`TYPE_ID`, MAX(CAST(A.`PERIOD_CODE` AS SIGNED)) AS MAX_PREIOD_CODE FROM `inspection`.`inspection_routine_period` a GROUP BY a.`TYPE_ID`) b ON a.TYPE_ID = b.TYPE_ID LEFT JOIN ( SELECT it.`TEMP_TYPE_ID`, it.`TEMP_TYPE_NAME` FROM `inspection`.`inspection_task_template` it GROUP BY it.`TEMP_TYPE_ID` )c ON a.TYPE_ID = c.TEMP_TYPE_ID WHERE 1 = 1
AND a.TYPE_ID = #{params.TYPE_ID}
ORDER BY a.TYPE_ID,CAST(A.`PERIOD_CODE` AS SIGNED)
